// Look for product cards with clickable areas
const productCards = document.querySelectorAll('[class*="product"]');
const productInfo = Array.from(productCards).slice(0, 3).map(card => ({
  html: card.outerHTML.substring(0, 200),
  links: Array.from(card.querySelectorAll('a')).map(a => a.href)
}));
productInfo;

// Get the actual structure of what's on the page
const mainContent = document.querySelector('main') || document.body;
const structure = {
  mainClasses: mainContent.className,
  childrenCount: mainContent.children.length,
  firstChildClasses: mainContent.children[0]?.className,
  hasImages: mainContent.querySelectorAll('img').length,
  hasLinks: mainContent.querySelectorAll('a').length,
  sampleHTML: mainContent.innerHTML.substring(0, 500)
};
structure;

// Wait for React to render and look for clickable products
const waitForProducts = () => {
  return new Promise((resolve) => {
    const checkProducts = () => {
      // Look for any clickable elements with product titles
      const titleElements = Array.from(document.querySelectorAll('h3, h4, h2, [class*="title"], [class*="name"]'));
      const productTitles = titleElements.filter(el => {
        const text = el.textContent.trim();
        return text.length > 10 && text.includes('Ring') || text.includes('Gold') || text.includes('Diamond');
      });

      if (productTitles.length > 0) {
        const results = productTitles.slice(0, 3).map(el => {
          const parent = el.closest('a') || el.parentElement?.closest('a');
          return {
            text: el.textContent.trim(),
            hasLink: !!parent,
            link: parent?.href || 'no link',
            parentTag: el.parentElement?.tagName
          };
        });
        resolve(results);
      } else {
        setTimeout(checkProducts, 200);
      }
    };
    checkProducts();
  });
};

waitForProducts();

