// Press Enter key in the search field
const searchInput = document.querySelector('input[placeholder*="Search"]');
if (searchInput) {
  const event = new KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  searchInput.dispatchEvent(event);
  'Enter pressed';
} else {
  'Search input not found';
}

// Click the search icon/button
const searchButton = document.querySelector('button[aria-label*="search"]') || 
                     document.querySelector('button:has(svg)');
if (searchButton) {
  searchButton.click();
  'Clicked search button';
} else {
  'Button not found';
}

// Scroll to bottom
window.scrollTo(0, document.body.scrollHeight);
'Scrolled to bottom';

// Check page state
({
  url: window.location.href,
  hasHeader: !!document.querySelector('header'),
  hasNav: !!document.querySelector('nav'),
  hasLogo: !!document.querySelector('img[alt*="Debenhams"]'),
  bodyHeight: document.body.scrollHeight,
  viewportScrollY: window.scrollY
});
